 pn(16,1,10,0,13,0,[7,7,7]);pn(1,14,10,-17,0,2,[5,4.6,4]);pn(1,14,10,17,0,2,[3,3.4,4]);pn(14,8,1,0,2,-17,[2.2,2,1.8]);
